from __future__ import annotations
from typing import Dict, List


def primes_below(n: int) -> List[int]:
    s = bytearray([1]) * n
    s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i :: i] = bytearray(len(s[i * i :: i]))
    return [i for i in range(n) if s[i]]


def root_count(coeffs: List[int], p: int) -> int:
    """Number of roots in F_p of the polynomial with coefficients (highest degree first)."""
    def ev(x: int) -> int:
        r = 0
        for c in coeffs:
            r = (r * x + c) % p
        return r
    return sum(1 for x in range(p) if ev(x) == 0)


def legendre(a: int, p: int) -> int:
    r = pow(a % p, (p - 1) // 2, p)
    return -1 if r == p - 1 else r


def identify_dial(coeffs: List[int], bad: List[int], candidates: List[int], bound: int) -> Dict[int, bool]:
    """For each candidate discriminant d, test [r(p)=1] <=> (d/p) = -1 on all good primes < bound."""
    ps = [p for p in primes_below(bound) if p not in bad and p > 2]
    rc = {p: root_count(coeffs, p) for p in ps}
    return {d: all((rc[p] == 1) == (legendre(d, p) == -1) for p in ps) for d in candidates}


if __name__ == "__main__":
    f = [1, 0, 0, 0, 20, 32]                 # x^5 + 20x + 32
    print(identify_dial(f, [2, 5], [-1, 2, -2, 5, -5, 10, -10], 3000))   # only -5 -> True

from __future__ import annotations
import math
from collections import Counter
from fractions import Fraction
from itertools import product
from typing import Callable, Dict, Hashable, List, Tuple


def fixed_points(n: int, x: int) -> int:
    """x = n*e + b encodes y -> (-1)^e y + b on Z/n."""
    e, b = divmod(x, n)
    return sum(1 for y in range(n) if ((y if e == 0 else -y) + b) % n == y)


def entropy(counts: List[int]) -> float:
    t = sum(counts)
    return -sum(c / t * math.log2(c / t) for c in counts if c)


def mutual_info(cells: List[Tuple[int, int]], T: Callable, V: Callable) -> float:
    a = Counter(T(c) for c in cells); b = Counter(V(c) for c in cells)
    ab = Counter((T(c), V(c)) for c in cells)
    return entropy(list(a.values())) + entropy(list(b.values())) - entropy(list(ab.values()))


def chebotarev_hint(n: int, ordered: bool) -> Dict[str, float]:
    F = [fixed_points(n, x) for x in range(2 * n)]
    cells = list(product(range(2 * n), repeat=2))
    T = (lambda c: (F[c[0]], F[c[1]])) if ordered else (lambda c: tuple(sorted((F[c[0]], F[c[1]]))))
    pair = lambda c: (c[0] // n, c[1] // n)
    prod_ = lambda c: (c[0] // n + c[1] // n) % 2
    ip, iq = mutual_info(cells, T, pair), mutual_info(cells, T, prod_)
    return {"I_pair": ip, "I_prod": iq, "hint": ip - iq,
            "pinned_product_row": abs(iq - entropy(list(Counter(prod_(c) for c in cells).values()))) < 1e-12}


if __name__ == "__main__":
    for n in (3, 5, 7, 9):
        print(n, chebotarev_hint(n, False), chebotarev_hint(n, True))

