def root_count(p: int) -> int:
    return sum(1 for x in range(p) if (pow(x, 5, p) + 20 * x + 32) % p == 0)


def H(c: Counter) -> float:
    t = sum(c.values())
    return -sum(v / t * math.log2(v / t) for v in c.values())


def plugin_hint(bound: int, m: int = 320) -> Tuple[int, float, float, float]:
    """Plug-in I(T; (p+q, q-p) mod m) - I(T; pq mod m) over all prime pairs 7 <= p < q < bound."""
    ps = [p for p in primes_below(bound) if p >= 7]
    rc = {p: root_count(p) for p in ps}
    T, J, P, TJ, TP = Counter(), Counter(), Counter(), Counter(), Counter()
    M = 0
    for i, p in enumerate(ps):
        for q in ps[i + 1 :]:
            t = (min(rc[p], rc[q]), max(rc[p], rc[q]))
            j = ((p + q) % m, (q - p) % m)
            v = (p * q) % m
            T[t] += 1; J[j] += 1; P[v] += 1; TJ[(t, j)] += 1; TP[(t, v)] += 1; M += 1
    ij = H(T) + H(J) - H(TJ)
    ip = H(T) + H(P) - H(TP)
    return M, ij, ip, ij - ip


